mapper.insert:
insert into sys_role_menu(role_code, fun_code) select requested.role_code, requested.fun_code from (
select #{item.roleCode} as role_code, #{item.funCode} as fun_code
) requested join sys_role r on r.role_code = requested.role_code where r.role_type = 'PLATFORM' and r.shop_code = '' and r.del_flag = '0'
